INSERT INTO `course` VALUES (1,2,'MBA',4,'<table border=\"\" cellpadding=\"0\" cellspacing=\"0\" style=\"width:100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td colspan=\"5\" style=\"height:61px; width:1083px\">\r\n			<h3><strong>COLLEGE - BHABHA ENGINEERING RESEARCH INSTITUTE, BHOPAL</strong></h3>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"height:40px; width:168px\"><span style=\"color:#cc6600\"><strong>COURSE</strong></span></td>\r\n			<td style=\"width:201px\"><span style=\"color:#cc6600\"><strong>BRANCHES</strong></span></td>\r\n			<td style=\"width:70px\"><span style=\"color:#cc6600\"><strong>SEATS</strong></span></td>\r\n			<td style=\"width:108px\"><span style=\"color:#cc6600\"><strong>DURATION</strong></span></td>\r\n			<td style=\"width:535px\"><span style=\"color:#cc6600\"><strong>ELIGIBILITY</strong></span></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"height:96px; width:168px\"><strong>MBA(FULL TIME)</strong></td>\r\n			<td style=\"width:201px\"><strong>HRM / FINANCIAL/ MARKETING/ IT/ PRODUCTION/ BANKING/ RETAIL/ IB / HOSPITAL MANAGEMENT</strong></td>\r\n			<td style=\"width:70px\"><strong>60</strong></td>\r\n			<td style=\"width:108px\"><strong>&nbsp;2 Years</strong></td>\r\n			<td style=\"text-align:justify; width:535px\"><strong>A candidate seeking admission to MBA and Allied Courses should be a Graduate with at least 50% marks and 45% marks in case of SC, ST, OBC (Excluding Creamy Layer) category of Madhya Pradesh.</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"height:20px\">&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td colspan=\"5\" style=\"height:61px; width:1083px\">\r\n			<h3><strong>COLLEGE - BHABHA ENGINEERING RESEARCH INSTITUTE - MCA</strong>&nbsp;</h3>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"height:40px; width:168px\"><span style=\"color:#cc6600\"><strong>COURSE</strong></span></td>\r\n			<td style=\"width:201px\"><span style=\"color:#cc6600\"><s