INSERT INTO `homepage_sections` VALUES (1,'hero_video','Hero Video & Stats Bar','AERIAL · BHOPAL CAMPUS','150 acres of<br><em>living, learning</em> landscape.','From the medical quadrangle to the engineering labs — a bird\'s-eye view of the community our students call home.','','new-media/image/hero/bhabha_2.mp4','','','{\"poster\":\"new-media/image/campus-aerial.png\",\"stats\":[{\"number\":\"15000\",\"suffix\":\"+\",\"commas\":true,\"label\":\"STUDENTS\"},{\"number\":\"850\",\"suffix\":\"+\",\"commas\":false,\"label\":\"FACULTY\"},{\"number\":\"200\",\"suffix\":\"+\",\"commas\":false,\"label\":\"PROGRAMS\"},{\"number\":\"15\",\"suffix\":\"\",\"commas\":false,\"label\":\"SCHOOLS\"},{\"number\":\"500\",\"suffix\":\"+\",\"commas\":false,\"label\":\"RECRUITERS\"},{\"number\":\"75\",\"suffix\":\"k+\",\"commas\":false,\"label\":\"ALUMNI\"},{\"number\":\"1200\",\"suffix\":\"+\",\"commas\":true,\"label\":\"PUBLICATIONS\"},{\"number\":\"150\",\"suffix\":\"ac\",\"commas\":false,\"label\":\"CAMPUS\"}]}',1,1,'2026-09-08 15:55:03'),(2,'chancellor_welcome','Chancellor\'s Welcome','CHANCELLOR\'S MESSAGE','A legacy of <em>excellence</em>.<br>A vision for tomorrow.','','<p><strong>Dr. Sadhna Kapoor</strong> is the Chancellor of BHABHA University. A visionary and a selfless leader with exceptional entrepreneurial, interpersonal, social and administrative skills; Dr. Sadhna Kapoor is passionate about technology and innovation, community development, social service, and interdisciplinary teaching and research.</p>\n<p>She has been awarded the title of “Honorary Professor” by the Academic Union Oxford, UK, reflecting her global dedication to educational innovation and excellence.</p>','new-media/image/hero/sadhna-mam.mp4','“We bridge academic brilliance with industrial pragmatism.”','DR. SADHNA KAPOOR · CHANCELLOR','{\n    \"recognitions\": [\n        {\n            \"title\": \"UGC\",\n            \"label\": \"RECOGNISED\"\n        },\n        {\n            \"title\": \"NAAC\",\n            \"label\": \"A+ GRADE\"\n        },\n        {\n            \"title\": \"AICTE\",\n            \"label\": \"APPROVED\"\n        }\n    ]\n}',1,2,'2026-09-08 15:44:58'),(3,'why_bhabha','Why Bhabha University','WHY BHABHA','A university built<br>for <em>impact.</em>','From accreditation to ecosystem — every dimension of the Bhabha experience is engineered for academic depth, global mobility and lifelong opportunity.','','','','','{\n    \"features\": [\n        {\n            \"icon\": \"fa fa-certificate\",\n            \"title\": \"NAAC & UGC Recognised\",\n            \"desc\": \"Accredited by NAAC; UGC recognised under 2(f) & 12(B).\"\n        },\n        {\n            \"icon\": \"fa fa-flask\",\n            \"title\": \"Research Excellence\",\n            \"desc\": \"120+ research labs, 250+ patents and 1,200+ publications.\"\n        },\n        {\n            \"icon\": \"fa fa-globe\",\n            \"title\": \"Global Collaborations\",\n            \"desc\": \"MoUs with 60+ international universities across 4 continents.\"\n        },\n        {\n            \"icon\": \"fa fa-mortar-board\",\n            \"title\": \"Outstanding Placements\",\n            \"desc\": \"98% placement rate with 500+ recruiters and packages up to ₹52 LPA.\"\n        },\n        {\n            \"icon\": \"fa fa-building-o\",\n            \"title\": \"Smart Campus\",\n            \"desc\": \"150-acre wifi-enabled green campus with smart classrooms.\"\n        },\n        {\n            \"icon\": \"fa fa-rocket\",\n            \"title\": \"Innovation Ecosystem\",\n            \"desc\": \"Incubation centre, student startups and industry mentoring.\"\n        }\n    ]\n}',1,3,'2026-09-08 16:31:17'),(4,'virtual_tour','Virtual Tour Showcase','Explore Campus · 360° Drone View','Virtual Tour of <em>Bhabha Campus</em>','Experience our breathtaking 150-acre green campus from the sky. Explore world-class academic blocks, research labs, sports arenas, and vibrant student life — all from right here.','','new-media/image/hero/bhabha_1.mp4','','','{\n    \"poster\": \"new-media\\/image\\/campus-aerial.png\",\n    \"badge1\": \"Live Campus Video\",\n    \"badge2\": \"Bhopal, MP\",\n    \"cards\": [\n        {\n            \"title\": \"150-Acre Green Campus\",\n            \"sub\": \"Smart Classrooms, Wifi & Hostels\"\n        },\n        {\n            \"title\": \"Central Library & Labs\",\n            \"sub\": \"120+ Hi-Tech Labs & Digital Library\"\n        }\n    ]\n}',1,4,'2026-09-08 15:44:58'),(5,'research_innovation','Research & Innovation','RESEARCH & INNOVATION','Knowledge that <em>moves</em> the<br>world forward.','From climate-resilient agriculture to AI in healthcare — our 120+ labs and research centres tackle the questions that matter most.','','new-media/image/research-students.png','','','{\"metrics\":[{\"target\":250,\"value\":\"250\",\"suffix\":\"+\",\"prefix\":\"\",\"commas\":false,\"label\":\"PATENTS FILED\"},{\"target\":1200,\"value\":\"1200\",\"suffix\":\"+\",\"prefix\":\"\",\"commas\":true,\"label\":\"PUBLICATIONS\"},{\"target\":85,\"value\":\"85\",\"suffix\":\"Cr\",\"prefix\":\"₹\",\"commas\":false,\"label\":\"ACTIVE GRANTS\"},{\"target\":60,\"value\":\"60\",\"suffix\":\"+\",\"prefix\":\"\",\"commas\":false,\"label\":\"GLOBAL MOUS\"}],\"highlight_icon\":\"fa fa-flask\",\"highlight_text\":\"Featured: DST-funded sustainable energy research lab — ₹2.4 Cr grant.\",\"button_text\":\"EXPLORE RESEARCH →\",\"button_url\":\"research.php\"}',1,5,'2026-09-09 11:02:56'),(6,'global_network','Global Network & MoUs','INTERNATIONAL','A truly <em>global</em> network.','60+ MoUs with leading universities across North America, Europe and Asia. Student exchange, joint research and dual degree pathways.','','','','','{\"tags\":[\"University of Toronto\",\"TU Munich\",\"NUS Singapore\",\"Monash\",\"Curtin\",\"UPenn\",\"Sheffield\",\"Kyoto University\",\"ETH Z\\u00fcrich\"],\"button_text\":\"APPLY NOW \\u2192\",\"button_url\":\"enquiry.php\"}',1,6,'2026-09-08 15:53:46'),(7,'insta_reels','Campus Instagram Reels','LIFE AT BHABHA · INSTAGRAM REELS','Inside the <em>University</em>','Watch real campus moments, student celebrations, and university highlights directly from our official Instagram feed.','','','','','{\n    \"reels\": [\n        {\n            \"id\": \"reel-1\",\n            \"title\": \"Campus Celebrations & Events\",\n            \"code\": \"Dbr0ycHAi-x\",\n            \"embed_url\": \"https:\\/\\/www.instagram.com\\/p\\/Dbr0ycHAi-x\\/embed\\/\",\n            \"insta_url\": \"https:\\/\\/www.instagram.com\\/reel\\/Dbr0ycHAi-x\\/\"\n        },\n        {\n            \"id\": \"reel-2\",\n            \"title\": \"Annual Fest & Activities\",\n            \"code\": \"DanDix7AeZq\",\n            \"embed_url\": \"https:\\/\\/www.instagram.com\\/p\\/DanDix7AeZq\\/embed\\/\",\n            \"insta_url\": \"https:\\/\\/www.instagram.com\\/reel\\/DanDix7AeZq\\/\"\n        },\n        {\n            \"id\": \"reel-3\",\n            \"title\": \"Hi-Tech Skill Labs & Practical\",\n            \"code\": \"Dacmhdnj8hJ\",\n            \"embed_url\": \"https:\\/\\/www.instagram.com\\/p\\/Dacmhdnj8hJ\\/embed\\/\",\n            \"insta_url\": \"https:\\/\\/www.instagram.com\\/reel\\/Dacmhdnj8hJ\\/\"\n        },\n        {\n            \"id\": \"reel-4\",\n            \"title\": \"University Highlights & Moments\",\n            \"code\": \"DaSehWXDgwj\",\n            \"embed_url\": \"https:\\/\\/www.instagram.com\\/p\\/DaSehWXDgwj\\/embed\\/\",\n            \"insta_url\": \"https:\\/\\/www.instagram.com\\/reel\\/DaSehWXDgwj\\/\"\n        }\n    ]\n}',1,7,'2026-09-08 15:44:58');
