INSERT INTO `jobs` VALUES (6,'Applications are invited for Faculty posts (Principal/Professor/Associate Professor/Assistant Professor) in Bhabha University. Dated 10.07.2024 (New)','','b643b0648e3475635f9bdffe5441a29d.jpg','2024-07-10 05:54:34'),(8,'Walk-in-Interview for Admission Counselor on 18 May 2024 at Bhabha University Bhopal. 17.5.2024 ','','b48d503adf14c761deee0db84c8e55bb.jpeg','2024-07-09 09:11:32'),(9,'Bhabha University has invited applications for the post of Nursing & Paramedical Faculty position. Dated 9.7.2024 (New)','','e6ade029c0c934ecbc0e783190cc566e.jpg','2024-07-09 09:10:09'),(10,'hr@bhabhauniversity.edu.in','',NULL,'2024-07-10 05:42:02');
