INSERT INTO `page` VALUES (1,'University Account Details','university-account-details','Admissions','University Account Details','<p style=\"text-align:justify\">Respected Parents/Students of Bhabha University are requested to deposit their Tution Fee directly in Union Bank of India, RKDF College Bhopal or through RTGS/NEFT and receipt given to account section of Bhabha University. The Bank details are as under :-</p>\r\n\r\n<h3>Fee Payment Through :</h3>\r\n\r\n<ul>\r\n	<li style=\"text-align:justify\"><strong>Account Name : Bhabha University</strong></li>\r\n	<li><strong>Account Number : 573801010050206 </strong></li>\r\n	<li><strong>IFSC CODE :&nbsp; UBIN0557382</strong></li>\r\n	<li><strong>Bank Name : Union Bank of India</strong></li>\r\n	<li><strong>Branch : RKDF College Bhopal</strong>\r\n	<hr /></li>\r\n</ul>\r\n\r\n<p><strong>Fee Payment Through</strong> : <strong><a href=\"http://m.p-y.tm/bhabhauniversity_nrweb\" target=\"_blank\"><span style=\"color:#3366ff\">Online PayTM</span></a></strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>Fee Payment Through</strong> : <strong><span style=\"color:#0066ff\"> Scan&nbsp;PayTM QR Code&nbsp;</span></strong></p>\r\n\r\n<p><img alt=\"\" src=\"https://www.bhabhauniversity.edu.in/upload/media/1ef67ce983b17dbdf127b7a85f3fb57e.jpeg\" style=\"height:289px; width:289px\" /></p>\r\n<!--<p>Click here : <strong><a href=\"https://www.bhabhauniversity.edu.in/page/2/\"><span style=\"color:#FF0000\">Online Fee Payment</span></a></strong></p> -->\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n',1),(2,'Online Fee Payment','online-fee-payment','Online Fee Payment','Online Fee Payment','<h2><strong><a href=\"http://m.p-y.tm/bhabhauniversity_nrweb\" target=\"_blank\"><span style=\"color:#0066ff\">Online Fee Payment Through PayTM </span></a></strong></h2>\r\n\r\n<h3><strong><span style=\"color:#0066ff\">Fee payment Through Scan&nbsp;PayTM QR Code&nbsp;</span></strong></h3>\r\n\r\n<p><strong><span style=\"color:#FF8C00\"><img alt=\"\" src=\"https://www.bhabhauniversity.edu.in/upload/media/1ef67ce983b17dbdf127b7a85f3fb57e.jpeg\" style=\"height:50%; width:50%\" /></span></strong></p>\r\n',1),(3,'Research at Glance','research-at-glance','Research','Research at Glance','<p><strong><a href=\"https://www.bhabhauniversity.edu.in/upload/media/7dc70afc87467ddda0130826042a76c4.pdf\" target=\"_blank\"><span style=\"color:rgb(34, 34, 34); font-family:arial,helvetica,sans-serif; font-size:small\">List of Ph.D. awarded&nbsp;</span></a></strong></p>\r\n\r\n<p><strong><a href=\"https://www.bhabhauniversity.edu.in/upload/media/1505c55b201dd04ac08cdb645d5c477e.pdf\" target=\"_blank\"><span style=\"color:rgb(34, 34, 34); font-family:arial,helvetica,sans-serif; font-size:small\">List of supervisor</span></a></strong></p>\r\n',1),(4,'Funding Agency','funding-agency','Research','Funding Agency','<p>&nbsp;</p>\r\n\r\n<ul>\r\n	<li><strong><a href=\"https://www.bhabhauniversity.edu.in/upload/media/de3688c4be7aeab7438aae75cba79696.pdf\"><span style=\"color:#FF8C00\">Funding Agency</span></a></strong></li>\r\n	<li><strong><a href=\"https://www.bhabhauniversity.edu.in/upload/media/ffe90b0c7e9e55b00b1207aee3ce3971.pdf\"><span style=\"color:#FF8C00\">Sponsoring detail</span></a></strong></li>\r\n</ul>\r\n',1),(5,'Publication','publication','Research','Publication','<p><strong><a href=\"https://www.bhabhauniversity.edu.in/upload/media/5c4dc9ec233200620ba878cf153175b0.pdf\"><span style=\"color:rgb(255, 140, 0)\">Engineering - Publication</span></a></strong></p>\r\n\r\n<p><strong><a href=\"https://www.bhabhauniversity.edu.in/upload/media/d428c7bc6903e8e8d816042e7b73fa7f.pdf\"><span style=\"color:rgb(255, 140, 0)\">Management - Publication</span></a></strong></p>\r\n\r\n<p><strong><a href=\"https://www.bhabhauniversity.edu.in/upload/media/e1d51b854b423c7682843d4f9a5d3dc0.pdf\"><span style=\"color:rgb(255, 140, 0)\">Pharmacy - Publication</span></a></strong></p>\r\n\r\n<p><strong><a href=\"https://www.bhabhauniversity.edu.in/upload/media/f339f251a7cb2467d1731aad07f210f8.pdf\"><span style=\"color:rgb(255, 140, 0)\">Education - Publication</span></a></strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n',1),(6,'Media','media','Vocational Courses','School of Media','<p style=\"text-align:center\"><img alt=\"\" src=\"https://www.bhabhauniversity.edu.in/upload/media/bf89de66660dc07c78256cdc4757a6c0.jpg\" style=\"float:left\" /></p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" src=\"https://www.bhabhauniversity.edu.in/upload/media/49a8ad9753898fd6a1cf1873105dba58.jpg\" /></p>\r\n\r\n<p style=\"text-align:center\"><img alt=\"\" src=\"https://www.bhabhauniversity.edu.in/upload/media/9b549c63fc1628bbcf86423147a94bb6.jpg\" /></p>\r\n',1),(7,'Hotel Management','hotel-management','Vocational Courses','RKDF INSTITUTE OF HOTEL MANAGEMENT & CAT. TECHNOLOGY','<p><img alt=\"\" src=\"https://www.bhabhauniversity.edu.in/upload/media/ad38aa2d445585fc5db90adee1d86085.jpg\" /><!--\r\n<h2><u><strong><span style=\"font-size:13px\">PROPOSED ONLINE CERTIFICATE COURSES DETAILS</span></strong></u></h2>\r\n\r\n<h3><span style=\"color:#A52A2A\">SESSION -- 2020-2021</span></h3>\r\n\r\n<table border=\"\" cellpadding=\"0\" cellspacing=\"0\">\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"width:33px\">\r\n			<p><strong><span style=\"color:#0066ff\">SN</span></strong></p>\r\n			</td>\r\n			<td style=\"width:205px\">\r\n			<p><strong><span style=\"color:#0066ff\">CERTIFICATE COURSE</span></strong></p>\r\n			</td>\r\n			<td style=\"width:124px\">\r\n			<p><strong><span style=\"color:#0066ff\">ELIGIBILITY</span></strong></p>\r\n			</td>\r\n			<td style=\"width:146px\">\r\n			<p><strong><span style=\"color:#0066ff\">DURATION</span></strong></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"width:33px\">\r\n			<p><strong>1.</strong></p>\r\n			</td>\r\n			<td style=\"width:205px\">\r\n			<p><strong>Certificate course in Indian Cuisine.</strong></p>\r\n			</td>\r\n			<td style=\"width:124px\">\r\n			<p><strong>Passed class 10